import * as React from "react";
import { Loader2Icon } from "lucide-react";

import { cn } from "@/lib/utils";

/**
 * figma: Spinner — Size = size-3 | size-4 | size-5 | size-6.
 *
 * Those Figma variants are Tailwind utilities, and the docs say
 * "Use the size-* utility class to change the size of the spinner", so size is
 * a class rather than a prop: `<Spinner className="size-6" />`.
 *
 * Inside a Button or Badge, add data-icon="inline-start" | "inline-end".
 */
function Spinner({ className, ...props }: React.ComponentProps<"svg">) {
  return (
    <Loader2Icon
      role="status"
      aria-label="Loading"
      data-slot="spinner"
      className={cn("size-4 shrink-0 animate-spin", className)}
      {...props}
    />
  );
}

export { Spinner };
